const PF=[['TikTok',['tiktok.com']],['Instagram',['instagram.com']],['Facebook',['facebook.com','fb.watch','fb.com']],['YouTube',['youtube.com','youtu.be']],['X / Twitter',['twitter.com','x.com','t.co']],['Pinterest',['pinterest.com','pin.it']],['Reddit',['reddit.com','redd.it']]];
function detect(u){try{const x=new URL(u);if(!/^https?:$/.test(x.protocol))return null;const h=x.hostname.replace(/^www\./,'');for(const[n,d]of PF)if(d.some(k=>h===k||h.endsWith('.'+k)))return n;return'Direct MP4 URL'}catch{return null}}
