function hist(j,status,m){if(!D.cfg.autoHist)return;D.history.unshift({id:uid(),mid:m?.id||'',name:j.name,platform:'Direct MP4 URL',t:Date.now(),fmt:(j.type.split('/')[1]||'file').toUpperCase(),size:m?.size||j.got,status,src:j.url,thumb:m?.thumb||''});D.history=D.history.slice(0,300);save()}
function pump(){let n=jobs.filter(j=>j.state==='running').length;for(const j of jobs)if(j.state==='queued'&&n<2){n++;j.run()}}
function enqueue(url,o){const j=new Job(url,o);jobs.unshift(j);notify('Download Started',j.name);act('Started '+j.name);pump();return j}
